/* New Styles for Gradient Border */
.custom-card {
  position: relative;
  margin: 20px;
  display: inline-block; /* Ensure cards are inline */
  padding: 20px;
  border-radius: 15px;
  overflow: hidden; /* Ensure overflow is hidden for border */
  box-shadow: 0 8px 16px rgba(0, 0, 0, 0.1);
  transition: transform 0.3s ease-in-out;
}

.custom-card::before,
.custom-card::after {
  content: '';
  position: absolute;
  z-index: -1;
  width: calc(100% + 10px);
  height: calc(100% + 10px);
  background-size: 200% 200%;
  border-radius: 15px;
  transition: all 0.4s ease-out;
}

.custom-card::before {
  top: -5px;
  left: -5px;
  background: linear-gradient(to right, #ff9966, #ff5e62, #ff2e92, #8635d3, #0099f7, #00e9db, #33ffa2, #85ff81);
}

.custom-card:hover::before {
  top: -10px;
  left: -10px;
  width: calc(100% + 20px);
  height: calc(100% + 20px);
}

.custom-card::after {
  bottom: -5px;
  right: -5px;
  background-color: #5b93a6;
  color: yellow;
}

.custom-card:hover::after {
  bottom: -10px;
  right: -10px;
  width: calc(100% + 20px);
  height: calc(100% + 20px);
}

.custom-card:hover {
  transform: translateY(-5px);
}

.image-container {
  position: relative;
  display: flex;
  align-items: center;
}

.image-container img {
  width: 100%;
  height: auto;
  display: block;
}

.text-container {
